// Builds the signed transport bundle (§12.6): the guest parts, ws.wasm and mlkem768.wasm,
// signed under suite 0x02 (§12.4, §14.1). Writes build/transport.skb and
// host/transport-bundle.ts (both gitignored).
//
// The author key is `--key <seed>` or transport/author.key, generated on first build, so
// each clone mints its own author (§12.5). Both halves of the hybrid key derive from it.

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import sodiumDefault from "libsodium-wrappers";
import { readGuestSource } from "./guest-source.mjs";
import { TRANSPORT_APP_CONFIG, TRANSPORT_SERVICE } from "./transport-config.mjs";
import { authorBundle, guestOpFraming, hybridAuthorKeysFromSeed } from "../build/scripts/bundle-author.js";
import { createMlDsa65, withMlDsa65 } from "../build/host/pq.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = join(__dirname, "..");

const args = process.argv.slice(2);
const keyFlag = (() => {
  const i = args.indexOf("--key");
  return i >= 0 && args[i + 1] ? args[i + 1] : undefined;
})();

const toHex = (b) => Buffer.from(b).toString("hex");

async function main() {
  await sodiumDefault.ready;
  let sodium = sodiumDefault;

  let seed;
  const keyPath = join(root, "transport", "author.key");
  if (keyFlag) {
    seed = Uint8Array.from(Buffer.from(keyFlag, "hex"));
  } else if (existsSync(keyPath)) {
    seed = Uint8Array.from(Buffer.from(readFileSync(keyPath, "utf8").trim(), "hex"));
  } else {
    seed = sodium.randombytes_buf(32);
    writeFileSync(keyPath, toHex(seed) + "\n", { mode: 0o600 });
    console.log("  wrote transport/author.key (keep it; this clone's bundle is signed by it)");
  }
  if (seed.length !== 32) throw new Error("--key must be 32 bytes of hex");

  // ML-DSA-65 mixed onto `sodium`, so one object signs and verifies both halves.
  const mldsaInstance = new WebAssembly.Instance(
    new WebAssembly.Module(readFileSync(join(root, "browser", "mldsa65.wasm"))), {});
  sodium = withMlDsa65(sodium, createMlDsa65(mldsaInstance));

  // Both keys from the one seed, so the same seed is the same author (§12.4).
  const keys = hybridAuthorKeysFromSeed(sodium, seed);

  const guest = readGuestSource(guestOpFraming());
  // RFC 6455 framing and the handshake KEM are bundle content.
  const wsWasm = readFileSync(join(root, "build", "ws.wasm"));
  const mlkemWasm = readFileSync(join(root, "browser", "mlkem768.wasm"));
  const { blob, author } = authorBundle(sodium, keys, {
    app: "transport",
    version: 1,
    // Local only: a `services` claim, never a peer-reachable `protocols` one.
    services: [TRANSPORT_SERVICE],
    modules: [
      { name: "ws", wasm: wsWasm },
      { name: "mlkem", wasm: mlkemWasm },
    ],
    guestSource: guest,
    // `link` goes only to the boot-selected transport or its explicit replacement (§12.5).
    guestRequires: ["node", "link", "timer"],
    // Signed defaults; an installation overrides any of them through LOCAL.
    guestConfig: TRANSPORT_APP_CONFIG,
  });
  // `author` is the key-set hash (bundle.ts `hybridAuthorId`), not the Ed25519 key.
  writeFileSync(join(root, "build", "transport.skb"), blob);
  const b64 = Buffer.from(blob).toString("base64");
  const ts = `// GENERATED by scripts/build-transport-bundle.mjs — DO NOT EDIT.
// The artifact-shipped transport bundle (§12.6), signed by the seed transport author
//   ${toHex(author)}
// under the hybrid suite 0x02 (§14.1).
import { fromBase64 } from "../services/util.js";
/** The local service id this bundle claims, for \`Shell.call\`. A replacement transport
 *  may name its own. */
export const TRANSPORT_SERVICE = "${TRANSPORT_SERVICE}";
const TRANSPORT_BUNDLE_B64 = "${b64}";
let decoded: Uint8Array | null = null;
/** The transport bundle's bytes (§12.6), a fresh copy per call. The b64 stays private:
 *  exported, it would land in the declaration file as a literal type. */
export function transportBundleBytes() {
    if (decoded === null) decoded = fromBase64(TRANSPORT_BUNDLE_B64);
    return decoded.slice();
}
`;
  writeFileSync(join(root, "host", "transport-bundle.ts"), ts);
  console.log(`  transport bundle: build/transport.skb (${blob.length} B)`);
  console.log(`  transport author: ${toHex(author)} (hybrid 0x02)`);
  console.log(`  ed25519 half:     ${toHex(keys.ed.publicKey)}`);
}

main().catch((e) => { console.error(e); process.exit(1); });
